//! `lez-registry`: command-line client for the LEZ Program Registry.

use clap::{Args, Parser, Subcommand};
use lee_core::{account::AccountId, program::ProgramHeader};
use lez_registry_sdk::{
    self as sdk, parse_account_id, pda,
    verify::{self, BuildConfig, LocalVerification, LocalVerifications},
    write::{Signer, Update},
    Config, EntryKind, EntryView, IdlStatus, Query, Registry,
};
use registry_core::EntryInput;
use std::path::{Path, PathBuf};
use std::process::{exit, Command};

/// The registry's own SPEL IDL, generated by `spel generate-idl`.
const REGISTRY_IDL: &str = include_str!("../../../artifacts/lez_registry-idl.json");

#[derive(Parser)]
#[command(name = "lez-registry", version, about = "LEZ Program Registry client")]
struct Cli {
    /// LEZ sequencer JSON-RPC endpoint.
    #[arg(
        long,
        env = "LEZ_SEQUENCER_URL",
        default_value = "http://127.0.0.1:3040",
        global = true
    )]
    sequencer: String,
    /// Logos Storage REST API base.
    #[arg(
        long,
        env = "LEZ_STORAGE_URL",
        default_value = "http://127.0.0.1:8080/api/storage/v1",
        global = true
    )]
    storage: String,
    /// Registry program address (its program header account).
    #[arg(long, env = "LEZ_REGISTRY_ID", global = true)]
    registry: Option<String>,
    /// Print JSON instead of text.
    #[arg(long, global = true)]
    json: bool,
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Args, Clone)]
struct Tx {
    /// `spel` binary used to build and sign transactions with your LEZ wallet.
    #[arg(long, env = "SPEL_BIN", default_value = "spel")]
    spel: PathBuf,
    /// Account paying the transaction fee (defaults to the first signer).
    #[arg(long, env = "LEZ_FEE_PAYER")]
    fee_payer: Option<String>,
}

#[derive(Args, Clone)]
struct Fields {
    #[arg(long)]
    version: Option<String>,
    #[arg(long)]
    description: Option<String>,
    /// IDL file to publish to Logos Storage (sets the IDL pointer).
    #[arg(long, conflicts_with = "idl_pointer")]
    idl: Option<PathBuf>,
    #[arg(long)]
    idl_pointer: Option<String>,
    /// Git checkout whose `--commit` is archived and published to Logos Storage (sets the code pointer).
    #[arg(long, conflicts_with = "code_pointer", requires = "commit")]
    source_repo: Option<PathBuf>,
    #[arg(long)]
    code_pointer: Option<String>,
    #[arg(long)]
    source_url: Option<String>,
    #[arg(long)]
    commit: Option<String>,
    /// Reproducible build configuration JSON (see docs/build-config.md).
    #[arg(long)]
    build_config: Option<String>,
}

#[derive(Subcommand)]
enum Cmd {
    /// Upload a file to Logos Storage and print its pointer.
    Publish { file: PathBuf },
    /// Archive `commit` of a git checkout and upload it to Logos Storage.
    PublishSource {
        #[arg(long, default_value = ".")]
        repo: PathBuf,
        #[arg(long)]
        commit: String,
    },
    /// Create the registry state account (once per deployment).
    Init {
        #[arg(long)]
        payer: String,
        #[command(flatten)]
        tx: Tx,
    },
    /// Register a program. Default is a deployer entry signed by the program header key.
    Register {
        #[arg(long)]
        program: String,
        /// Register as a third party, signed by `--author`.
        #[arg(long, requires = "author")]
        third_party: bool,
        #[arg(long)]
        author: Option<String>,
        #[arg(long)]
        name: String,
        #[arg(long)]
        author_name: String,
        #[command(flatten)]
        fields: Fields,
        #[command(flatten)]
        tx: Tx,
    },
    /// Update an entry. Only its author can sign. Unset fields keep their value.
    Update {
        #[arg(long)]
        program: String,
        /// Third-party author whose entry to update; omit for the deployer entry.
        #[arg(long)]
        author: Option<String>,
        #[command(flatten)]
        fields: Fields,
        #[command(flatten)]
        tx: Tx,
    },
    /// Transfer a third-party entry to a new author. Both must sign.
    Transfer {
        #[arg(long)]
        entry: String,
        #[arg(long)]
        from: String,
        #[arg(long)]
        to: String,
        #[arg(long)]
        new_author_name: String,
        #[command(flatten)]
        tx: Tx,
    },
    /// Resolve a program id to its entries' metadata and IDL.
    Lookup { program: String },
    /// Enumerate all entries.
    List,
    /// Search entries by name and/or author (case-insensitive substring).
    Search {
        #[arg(long)]
        name: Option<String>,
        #[arg(long)]
        author: Option<String>,
        #[arg(long, value_parser = ["deployer", "third-party"])]
        kind: Option<String>,
    },
    /// Rebuild an entry's recorded source and compare with the deployed ImageID.
    Verify {
        program: String,
        /// Verify this third-party author's entry instead of the deployer entry.
        #[arg(long)]
        author: Option<String>,
        /// Use an already unpacked source tree instead of fetching the code pointer.
        #[arg(long)]
        source_dir: Option<PathBuf>,
        /// Compare an already built binary (skips the rebuild).
        #[arg(long)]
        binary: Option<PathBuf>,
        /// Record a match as "locally verified" for this user.
        #[arg(long)]
        mark: bool,
    },
    /// Show this user's locally verified programs.
    Verified,
    /// Print PDAs (state, deployer entry, slot) for scripting.
    Pda {
        #[arg(long)]
        program: Option<String>,
        #[arg(long)]
        author: Option<String>,
        #[arg(long)]
        slot: Option<u64>,
    },
}

fn die(msg: impl std::fmt::Display) -> ! {
    eprintln!("error: {msg}");
    exit(1)
}

fn id(s: &str) -> AccountId {
    parse_account_id(s).unwrap_or_else(|e| die(format!("bad account id `{s}`: {e}")))
}

fn registry(cli: &Cli) -> Registry {
    let rid = cli
        .registry
        .as_deref()
        .unwrap_or_else(|| die("--registry / LEZ_REGISTRY_ID is required"));
    Registry::new(Config {
        sequencer_url: cli.sequencer.clone(),
        storage_url: cli.storage.clone(),
        registry_id: id(rid),
    })
}

fn signer(tx: &Tx) -> Signer {
    let dir = verify::home_dir();
    std::fs::create_dir_all(&dir).unwrap_or_else(|e| die(e));
    let idl_path = dir.join("lez_registry-idl.json");
    std::fs::write(&idl_path, REGISTRY_IDL).unwrap_or_else(|e| die(e));
    Signer {
        spel_bin: tx.spel.clone(),
        idl_path,
        fee_payer: tx.fee_payer.clone(),
    }
}

fn git_archive(repo: &Path, commit: &str) -> Vec<u8> {
    let out = Command::new("git")
        .arg("-C")
        .arg(repo)
        .args(["archive", "--format=tar.gz", commit])
        .output()
        .unwrap_or_else(|e| die(format!("git: {e}")));
    if !out.status.success() {
        die(format!(
            "git archive failed: {}",
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    out.stdout
}

fn publish_fields(reg: &Registry, f: &Fields) -> (Option<String>, Option<String>) {
    let idl = f.idl.as_ref().map(|p| {
        let bytes = std::fs::read(p).unwrap_or_else(|e| die(format!("{}: {e}", p.display())));
        sdk::parse_idl(&bytes).unwrap_or_else(|e| die(format!("{}: {e}", p.display())));
        reg.storage.upload(&bytes).unwrap_or_else(|e| die(e))
    });
    let code = f.source_repo.as_ref().map(|r| {
        let commit = f
            .commit
            .as_deref()
            .unwrap_or_else(|| die("--commit is required with --source-repo"));
        reg.storage
            .upload(&git_archive(r, commit))
            .unwrap_or_else(|e| die(e))
    });
    (
        idl.or_else(|| f.idl_pointer.clone()),
        code.or_else(|| f.code_pointer.clone()),
    )
}

fn kind_label(v: &EntryView) -> &'static str {
    match (v.entry.kind, v.verified_deployer) {
        (EntryKind::Deployer, true) => "DEPLOYER (signed by program header)",
        (EntryKind::Deployer, false) => "DEPLOYER? (PDA mismatch: do not trust)",
        (EntryKind::ThirdParty, _) => "third-party",
    }
}

fn print_entry(v: &EntryView, idl: Option<&IdlStatus>, marks: &LocalVerifications) {
    let e = &v.entry;
    println!("{} {} [{}]", e.name, e.version, kind_label(v));
    println!("  program      {}", v.program_id);
    println!("  entry        {}  (slot {})", v.entry_id, e.index);
    println!("  author       {} ({})", e.author_name, v.author);
    println!("  description  {}", e.description);
    println!(
        "  registered   {} ms (block {}), updated {} ms",
        e.registered_at, e.registered_block, e.updated_at
    );
    println!(
        "  image id     {}{}",
        v.image_id,
        if e.header_immutable {
            " (immutable)"
        } else {
            ""
        }
    );
    println!("  idl          {}", e.idl_pointer);
    println!("  code         {}", e.code_pointer);
    if !e.source_url.is_empty() {
        println!("  source url   {}", e.source_url);
    }
    println!("  commit       {}", e.commit);
    println!("  build        {}", e.build_config);
    let verified = marks.is_verified(&v.program_id, &v.image_id);
    println!(
        "  local verify {}",
        if verified {
            "LOCALLY VERIFIED"
        } else {
            "not verified by you"
        }
    );
    match idl {
        Some(IdlStatus::Available { idl }) => {
            let ixs: Vec<&str> = idl["instructions"]
                .as_array()
                .map(|a| a.iter().filter_map(|i| i["name"].as_str()).collect())
                .unwrap_or_default();
            println!(
                "  IDL          available: {} instruction(s): {}",
                ixs.len(),
                ixs.join(", ")
            );
        }
        Some(IdlStatus::Unavailable { reason }) => {
            println!("  IDL          IDL unavailable ({reason})")
        }
        None => {}
    }
}

fn print_json(v: &impl serde::Serialize) {
    println!("{}", serde_json::to_string_pretty(v).unwrap_or_default());
}

fn main() {
    let cli = Cli::parse();
    let marks = LocalVerifications::load().unwrap_or_default();
    match &cli.cmd {
        Cmd::Publish { file } => {
            let bytes =
                std::fs::read(file).unwrap_or_else(|e| die(format!("{}: {e}", file.display())));
            let s = sdk::StorageClient::new(&cli.storage);
            println!("{}", s.upload(&bytes).unwrap_or_else(|e| die(e)));
        }
        Cmd::PublishSource { repo, commit } => {
            let s = sdk::StorageClient::new(&cli.storage);
            println!(
                "{}",
                s.upload(&git_archive(repo, commit))
                    .unwrap_or_else(|e| die(e))
            );
        }
        Cmd::Init { payer, tx } => {
            let reg = registry(&cli);
            signer(tx)
                .initialize(&reg, &id(payer))
                .unwrap_or_else(|e| die(e));
            println!(
                "initialised registry state {}",
                pda::state(&reg.config.registry_id)
            );
        }
        Cmd::Register {
            program,
            third_party,
            author,
            name,
            author_name,
            fields,
            tx,
        } => {
            let reg = registry(&cli);
            let (idl_pointer, code_pointer) = publish_fields(&reg, fields);
            let need = |v: &Option<String>, f: &str| {
                v.clone()
                    .unwrap_or_else(|| die(format!("--{f} is required")))
            };
            let input = EntryInput {
                name: name.clone(),
                version: need(&fields.version, "version"),
                author_name: author_name.clone(),
                description: need(&fields.description, "description"),
                idl_pointer: need(&idl_pointer, "idl or --idl-pointer"),
                code_pointer: need(&code_pointer, "source-repo or --code-pointer"),
                source_url: fields.source_url.clone().unwrap_or_default(),
                commit: need(&fields.commit, "commit"),
                build_config: need(&fields.build_config, "build-config"),
            };
            if let Err(e) = BuildConfig::parse(&input.build_config) {
                die(e);
            }
            let s = signer(tx);
            let entry = if *third_party {
                let a = id(author.as_deref().unwrap_or_default());
                s.register_third_party(&reg, &id(program), &a, &input)
            } else {
                s.register_deployer(&reg, &id(program), &input)
            }
            .unwrap_or_else(|e| die(e));
            println!("registered entry {entry}");
        }
        Cmd::Update {
            program,
            author,
            fields,
            tx,
        } => {
            let reg = registry(&cli);
            let p = id(program);
            let a = author.as_deref().map(id);
            let entry_id = match &a {
                None => pda::deployer_entry(&reg.config.registry_id, &p),
                Some(a) => pda::third_party_entry(&reg.config.registry_id, &p, a),
            };
            let cur = reg
                .entry_at(&entry_id)
                .unwrap_or_else(|e| die(e))
                .unwrap_or_else(|| die("no such entry"));
            let (idl_pointer, code_pointer) = publish_fields(&reg, fields);
            let or = |v: &Option<String>, d: &str| v.clone().unwrap_or_else(|| d.to_string());
            let e = &cur.entry;
            let u = Update {
                version: or(&fields.version, &e.version),
                description: or(&fields.description, &e.description),
                idl_pointer: or(&idl_pointer, &e.idl_pointer),
                code_pointer: or(&code_pointer, &e.code_pointer),
                source_url: or(&fields.source_url, &e.source_url),
                commit: or(&fields.commit, &e.commit),
                build_config: or(&fields.build_config, &e.build_config),
            };
            signer(tx)
                .update(&reg, &entry_id, a.as_ref(), &u)
                .unwrap_or_else(|e| die(e));
            println!("updated entry {entry_id}");
        }
        Cmd::Transfer {
            entry,
            from,
            to,
            new_author_name,
            tx,
        } => {
            let reg = registry(&cli);
            signer(tx)
                .transfer(&reg, &id(entry), &id(from), &id(to), new_author_name)
                .unwrap_or_else(|e| die(e));
            println!("transferred entry {entry} to {to}");
        }
        Cmd::Lookup { program } => {
            let reg = registry(&cli);
            let resolved = reg.resolve(&id(program)).unwrap_or_else(|e| die(e));
            if cli.json {
                return print_json(&resolved);
            }
            if resolved.is_empty() {
                println!("no registry entries for {program}");
            }
            for r in &resolved {
                print_entry(&r.view, Some(&r.idl), &marks);
            }
        }
        Cmd::List | Cmd::Search { .. } => {
            let reg = registry(&cli);
            let q = match &cli.cmd {
                Cmd::Search { name, author, kind } => Query {
                    name: name.clone(),
                    author: author.clone(),
                    kind: kind.as_deref().map(|k| {
                        if k == "deployer" {
                            EntryKind::Deployer
                        } else {
                            EntryKind::ThirdParty
                        }
                    }),
                },
                _ => Query::default(),
            };
            let found = reg.search(&q).unwrap_or_else(|e| die(e));
            if cli.json {
                return print_json(&found);
            }
            println!(
                "{} entr{}",
                found.len(),
                if found.len() == 1 { "y" } else { "ies" }
            );
            for v in &found {
                print_entry(v, None, &marks);
            }
        }
        Cmd::Verify {
            program,
            author,
            source_dir,
            binary,
            mark,
        } => verify_cmd(
            &cli,
            program,
            author.as_deref(),
            source_dir.as_deref(),
            binary.as_deref(),
            *mark,
        ),
        Cmd::Verified => print_json(&marks.programs),
        Cmd::Pda {
            program,
            author,
            slot,
        } => {
            let rid = id(cli
                .registry
                .as_deref()
                .unwrap_or_else(|| die("--registry is required")));
            println!("state {}", pda::state(&rid));
            if let Some(p) = program.as_deref().map(id) {
                println!("deployer_entry {}", pda::deployer_entry(&rid, &p));
                if let Some(a) = author.as_deref().map(id) {
                    println!("third_party_entry {}", pda::third_party_entry(&rid, &p, &a));
                }
            }
            if let Some(i) = slot {
                println!("slot {}", pda::slot(&rid, *i));
            }
        }
    }
}

fn verify_cmd(
    cli: &Cli,
    program: &str,
    author: Option<&str>,
    source_dir: Option<&Path>,
    binary: Option<&Path>,
    mark: bool,
) {
    let reg = registry(cli);
    let p = id(program);
    let entry_id = match author.map(id) {
        None => pda::deployer_entry(&reg.config.registry_id, &p),
        Some(a) => pda::third_party_entry(&reg.config.registry_id, &p, &a),
    };
    let view = reg
        .entry_at(&entry_id)
        .unwrap_or_else(|e| die(e))
        .unwrap_or_else(|| die("no such entry"));
    let header_acc = reg.rpc.get_account(&p).unwrap_or_else(|e| die(e));
    if header_acc.program_owner != registry_core::PROGRAM_LOADER_ACCOUNT_ID {
        die("program id is not a deployed program header");
    }
    let header = ProgramHeader::from_bytes(header_acc.data.as_ref())
        .unwrap_or_else(|| die("bad program header"));
    let bin = match binary {
        Some(b) => b.to_path_buf(),
        None => {
            let cfg = BuildConfig::parse(&view.entry.build_config).unwrap_or_else(|e| die(e));
            let src = match source_dir {
                Some(d) => d.to_path_buf(),
                None => {
                    let dir = verify::home_dir().join("sources").join(&view.image_id);
                    let _ = std::fs::remove_dir_all(&dir);
                    eprintln!("fetching source {}", view.entry.code_pointer);
                    let archive = reg
                        .storage
                        .fetch(&view.entry.code_pointer)
                        .unwrap_or_else(|e| die(e));
                    verify::unpack(&archive, &dir).unwrap_or_else(|e| die(e));
                    dir
                }
            };
            eprintln!("rebuilding {} with {}", src.display(), cfg.builder);
            verify::rebuild(&src, &cfg).unwrap_or_else(|e| die(e))
        }
    };
    let bytes = std::fs::read(&bin).unwrap_or_else(|e| die(format!("{}: {e}", bin.display())));
    let built = verify::image_id_of(&bytes).unwrap_or_else(|e| die(e));
    let cmp = verify::compare(built, &header, &view.entry);
    if cli.json {
        print_json(&cmp);
    } else {
        println!("built   {}", cmp.built_image_id);
        println!("header  {}", cmp.header_image_id);
        println!("entry   {}", cmp.entry_image_id);
        println!(
            "{}",
            if cmp.matches {
                "MATCH: rebuilt source produces the deployed program"
            } else {
                "MISMATCH"
            }
        );
    }
    if !cmp.matches {
        exit(2);
    }
    if mark {
        let mut marks = LocalVerifications::load().unwrap_or_default();
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.as_secs());
        marks.programs.insert(
            view.program_id.clone(),
            LocalVerification {
                image_id: cmp.header_image_id.clone(),
                entry_id: view.entry_id.clone(),
                commit: view.entry.commit.clone(),
                code_pointer: view.entry.code_pointer.clone(),
                verified_at_unix: now,
            },
        );
        marks.save().unwrap_or_else(|e| die(e));
        println!(
            "marked {} as locally verified ({})",
            view.program_id,
            LocalVerifications::path().display()
        );
    }
}
